INSERT INTO `avis` VALUES (1,5,'Super moment','Super accueil et trés beaux parcours.','public','2026-05-19 17:03:47',1,NULL,NULL,1),(2,4,NULL,'Agréable pour une fin de matinée.','public','2026-05-19 17:03:47',1,NULL,NULL,2),(3,3,'BASMA JTM (pas)','les gens sont beaux','public','2026-05-19 17:10:52',2,NULL,NULL,2),(4,5,'Un incontournable','Vue imprenable depuis le sommet, surtout au coucher du soleil. La file d\'attente est longue mais ça vaut vraiment le coup.','public','2026-05-26 15:29:37',3,NULL,NULL,3),(5,4,'Magnifique mais bondé','L\'endroit est splendide, mais la foule en été est étouffante. Préférez y aller tôt le matin.','public','2026-05-26 15:29:37',4,NULL,NULL,3),(6,3,'Décevant la nuit','Les illuminations durent seulement quelques minutes, puis plus rien. La montée vaut plus que le spectacle nocturne.','public','2026-05-26 15:29:37',6,NULL,NULL,3),(7,5,'Mon rêve réalisé','J\'en rêvais depuis enfant. La réalité dépasse l\'imaginaire. Moment magique.','prive','2026-05-26 15:29:37',8,NULL,NULL,3),(8,5,'Une journée entière ne suffit pas','Tellement de chefs-d\'œuvre que c\'est presque écrasant. La Joconde est plus petite qu\'on imagine.','public','2026-05-26 15:29:37',5,NULL,NULL,4),(9,4,'Incontournable','La collection est phénoménale. Achetez les billets en ligne, la queue est interminable sinon.','public','2026-05-26 15:29:37',7,NULL,NULL,4),(10,2,'Trop grand, trop monde','Difficile de profiter sereinement avec autant de visiteurs. Le contenu est extraordinaire mais l\'expérience stressante.','public','2026-05-26 15:29:37',9,NULL,NULL,4),(11,5,'Coup de cœur absolu','La Vénus de Milo m\'a cloué sur place. Un temple de l\'art.','prive','2026-05-26 15:29:37',10,NULL,NULL,4),(12,5,'Oasis de couleurs','Le bleu Majorelle est encore plus vibrant en vrai. Un havre de paix au milieu du chaos de Marrakech.','public','2026-05-26 15:29:37',4,NULL,NULL,5),(13,4,'Très beau','Plantes rares, couleurs intenses, endroit calme. Un peu cher pour la taille mais ça vaut le détour.','public','2026-05-26 15:29:37',3,NULL,NULL,5),(14,5,'Coup de cœur de Marrakech','Meilleur endroit de toute la ville selon moi. Mieux que la médina en termes de sérénité.','public','2026-05-26 15:29:37',8,NULL,NULL,5),(15,5,'Vivant et authentique','La nuit tombée, la place s\'embrase. Musiciens, conteurs, vendeurs de jus... un spectacle gratuit permanent.','public','2026-05-26 15:29:37',6,NULL,NULL,6),(16,3,'Attention aux arnaques','L\'ambiance est unique mais soyez vigilants aux photographes avec singes ou serpents qui réclament de l\'argent.','public','2026-05-26 15:29:37',5,NULL,NULL,6),(17,4,'Expérience inoubliable','Incroyable melting-pot. Venez le soir pour profiter de l\'atmosphère des food stalls.','public','2026-05-26 15:29:37',10,NULL,NULL,6),(18,5,'Spirituel et grandiose','Le torii géant et les lanternes rouges créent une atmosphère hors du temps. Incontournable à Tokyo.','public','2026-05-26 15:29:37',7,NULL,NULL,7),(19,4,'Magique mais touristique','Très beau temple, mais le marché attenant est clairement orienté touristes. L\'architecture vaut le déplacement.','public','2026-05-26 15:29:37',9,NULL,NULL,7),(20,5,'Mon endroit préféré au Japon','La fumée de l\'encens et les prières du matin... une atmosphère unique. Venez à l\'ouverture.','public','2026-05-26 15:29:37',5,NULL,NULL,7),(21,3,'Bien mais surcoté','Le temple en lui-même est beau mais la foule rend l\'expérience difficile. Préférez les temples plus calmes de Kyoto.','prive','2026-05-26 15:29:37',3,NULL,NULL,7),(22,5,'Comme dans un film','Se balader dans les ruelles de Gion au crépuscule est une expérience hors du temps. J\'ai croisé une vraie geisha.','public','2026-05-26 15:29:37',4,NULL,NULL,8),(23,4,'Authentique','Le quartier a su préserver son architecture traditionnelle. Evitez les heures de pointe pour en profiter vraiment.','public','2026-05-26 15:29:37',6,NULL,NULL,8),(24,5,'L\'âme du Japon','Gion représente parfaitement ce que j\'aime dans la culture japonaise. La beauté dans les détails.','public','2026-05-26 15:29:37',10,NULL,NULL,8),(25,5,'Impressionnant','Difficile de ne pas ressentir le poids de l\'histoire en entrant dans l\'arène. Prenez l\'audioguide.','public','2026-05-26 15:29:37',8,NULL,NULL,9),(26,4,'Magnifique vestige','L\'état de conservation est remarquable pour 2000 ans d\'histoire. La visite du forum romain est incluse, ne la ratez pas.','public','2026-05-26 15:29:37',9,NULL,NULL,9),(27,3,'Bien mais file interminable','Réservez absolument en ligne. Sinon compter 3h de queue minimum en été. L\'intérieur en vaut la peine.','public','2026-05-26 15:29:37',7,NULL,NULL,9),(28,5,'Frissons garantis','Imaginer les gladiateurs ici donne vraiment le vertige. Un des sites antiques les mieux préservés du monde.','prive','2026-05-26 15:29:37',5,NULL,NULL,9),(29,5,'Une œuvre vivante','Gaudí a pensé chaque pierre. L\'intérieur baigné de lumière colorée est irréel. Un chef-d\'œuvre en construction.','public','2026-05-26 15:29:37',3,NULL,NULL,10),(30,5,'Époustouflant','Aucune photo ne rend justice à l\'effet que ça produit en vrai. La forêt de colonnes à l\'intérieur est sublime.','public','2026-05-26 15:29:37',4,NULL,NULL,10),(31,4,'Très beau mais cher','L\'entrée est onéreuse mais la visite est dense. Prenez le billet avec accès aux tours pour la vue sur Barcelone.','public','2026-05-26 15:29:37',6,NULL,NULL,10),(32,2,'Surcoté selon moi','Je ne suis pas fan de l\'architecture de Gaudí en général. L\'extérieur est impressionnant mais l\'intérieur m\'a moins convaincu.','public','2026-05-26 15:29:37',10,NULL,NULL,10),(33,5,'Architecture manuéline parfaite','Les sculptures en pierre sont d\'une finesse incroyable. L\'une des plus belles constructions que j\'aie jamais vues.','public','2026-05-26 15:29:37',8,NULL,NULL,11),(34,4,'Beau et gratuit le dimanche','L\'entrée est gratuite le dimanche matin. L\'architecture est vraiment unique, typiquement portugaise.','public','2026-05-26 15:29:37',3,NULL,NULL,11),(35,5,'Incontournable à Lisbonne','On est soufflé par la richesse des détails sculptés. À ne pas manquer avec la Tour de Belém juste à côté.','public','2026-05-26 15:29:37',5,NULL,NULL,11),(36,5,'Le meilleur musée d\'Europe','La Ronde de nuit de Rembrandt en vrai c\'est une autre dimension. Le bâtiment lui-même est une œuvre.','public','2026-05-26 15:29:37',9,NULL,NULL,12),(37,4,'Collection impressionnante','L\'âge d\'or hollandais est superbement représenté. Prévoyez au moins 3h.','public','2026-05-26 15:29:37',7,NULL,NULL,12),(38,4,'Incontournable','Si vous êtes à Amsterdam, ce musée est un passage obligé. La cour intérieure est magnifique.','public','2026-05-26 15:29:37',4,NULL,NULL,12),(39,5,'Poumon de New York','Se balader ici après des heures dans la jungle de béton new-yorkaise, c\'est une renaissance. Immense et varié.','public','2026-05-26 15:29:37',6,NULL,NULL,13),(40,4,'Très agréable','Le lac, les pelouses, le zoo... on peut y passer une journée entière. Idéal pour un pique-nique.','public','2026-05-26 15:29:37',10,NULL,NULL,13),(41,3,'Bien mais moins fou qu\'attendu','C\'est un beau parc, mais j\'en attendais peut-être trop. Intéressant surtout pour le contexte urbain autour.','public','2026-05-26 15:29:37',8,NULL,NULL,13),(42,5,'Berceau de l\'Occident','Monter sur l\'Acropole et voir le Parthénon depuis là-haut est un moment que je n\'oublierai jamais.','public','2026-05-26 15:29:37',3,NULL,NULL,14),(43,4,'Majestueux','Malheureusement en travaux lors de ma visite mais même ainsi l\'émotion est là. La vue sur Athènes vaut le détour.','public','2026-05-26 15:29:37',5,NULL,NULL,14),(44,5,'Intemporel','Des pierres vieilles de 2500 ans qui tiennent encore debout. C\'est presque miraculeux.','public','2026-05-26 15:29:37',9,NULL,NULL,14),(45,5,'Bouddha couché immense','Le Bouddha couché de 46 mètres est une vision saisissante. Les pieds en nacre sont fascinants.','public','2026-05-26 15:29:37',7,NULL,NULL,15),(46,4,'Très beau temple','Moins connu que le Palais Royal mais tout aussi impressionnant. Le massage thaï proposé sur place est excellent.','public','2026-05-26 15:29:37',4,NULL,NULL,15),(47,4,'Paisible et splendide','On oublie facilement qu\'on est en pleine capitale. Prenez le temps de flâner entre les stupas dorés.','public','2026-05-26 15:29:37',6,NULL,NULL,15),(48,5,'La Naissance de Vénus en vrai','Voir le tableau de Botticelli de ses propres yeux est une expérience unique. La collection est extraordinaire.','public','2026-05-26 15:29:37',10,NULL,NULL,16),(49,4,'Musée incontournable','File d\'attente très longue même avec réservation. Mais la qualité des collections justifie tout.','public','2026-05-26 15:29:37',8,NULL,NULL,16),(50,5,'Paradis de la Renaissance','Raphaël, Michel-Ange, Léonard... on en sort transformé. Prévoir la journée entière.','prive','2026-05-26 15:29:37',3,NULL,NULL,16),(51,5,'Immensité gothique','La plus grande cathédrale gothique au monde... et ça se voit. La Giralda offre une vue panoramique sur Séville.','public','2026-05-26 15:29:37',5,NULL,NULL,17),(52,4,'Impressionnante','La tombe de Christophe Colomb est portée par quatre rois... un symbole fort. L\'intérieur est richissime.','public','2026-05-26 15:29:37',9,NULL,NULL,17),(53,3,'Bien mais trop de monde','L\'architecture est magnifique mais la gestion du flux de visiteurs laisse à désirer. Allez-y tôt.','public','2026-05-26 15:29:37',7,NULL,NULL,17),(54,4,'Vraiment chouette','Vraiment très bien, juste un peu de monde aux heures de pointe.','public','2026-05-26 20:37:26',12,NULL,NULL,75),(55,2,'Un peu déçu','Franchement surcoté par rapport à la réputation. Décevant.','public','2026-05-26 20:37:26',12,NULL,NULL,99),(56,4,'Ça vaut le détour','Superbe découverte, on recommande chaudement. Prévoyez du temps.','public','2026-05-26 20:37:26',12,NULL,NULL,48),(57,5,'Inoubliable','Le genre d\'endroit qui justifie tout le voyage à lui seul.','public','2026-05-26 20:37:26',13,NULL,NULL,79),(58,4,'Très belle découverte','On a passé un excellent moment, à refaire. Petit conseil : réser