INSERT INTO `commentaire` VALUES (1,'Totalement d\'accord ! Le coucher de soleil depuis le sommet est magique.','2026-05-26 15:29:37',4,4,NULL),(2,'Le mieux c\'est d\'y aller en semaine pour éviter la foule du week-end.','2026-05-26 15:29:37',5,4,NULL),(3,'Je confirme, acheter en ligne c\'est indispensable au Louvre.','2026-05-26 15:29:37',3,9,NULL),(4,'Le bleu Majorelle est une couleur vraiment unique, on ne la retrouve nulle part ailleurs.','2026-05-26 15:29:37',6,12,NULL),(5,'Oui, venez tôt le matin au Sensoji, c\'est beaucoup plus serein avant les touristes.','2026-05-26 15:29:37',5,18,NULL),(6,'La Ronde de nuit m\'a aussi scotché ! Le format est gigantesque en vrai.','2026-05-26 15:29:37',4,36,NULL),(7,'Les Hiéronymites sont souvent moins visités que la Tour de Belém mais c\'est bien meilleur !','2026-05-26 15:29:37',5,33,NULL),(8,'Gaudí est un génie. Chaque visite révèle de nouveaux détails.','2026-05-26 15:29:37',6,29,NULL),(9,'J\'ai aussi été frappé par la taille du Wat Pho. Le massage thaï sur place est vraiment bien.','2026-05-26 15:29:37',3,45,NULL),(10,'La vue depuis la Giralda de nuit est également splendide si vous pouvez y aller le soir.','2026-05-26 15:29:37',6,51,NULL),(11,'poulet','2026-05-26 15:43:57',11,4,1),(12,'wow','2026-05-26 16:09:49',11,4,1),(13,'demain','2026-05-26 16:10:05',11,6,NULL),(14,'Pas convaincu perso, mais je comprends le point de vue.','2026-05-26 20:37:26',64,59,NULL),(15,'Bon à savoir, merci pour le conseil.','2026-05-26 20:37:26',101,63,NULL),(16,'Le meilleur moment reste tôt le matin.','2026-05-26 20:37:26',21,67,NULL),(17,'J\'y étais le mois dernier, exactement la même impression.','2026-05-26 20:37:26',24,78,NULL),(18,'Pas convaincu perso, mais je comprends le point de vue.','2026-05-26 20:37:26',25,81,NULL),(19,'Tout à fait d\'accord avec toi !','2026-05-26 20:37:26',89,85,NULL),(20,'Complètement validé, magique en vrai !','2026-05-26 20:37:26',31,86,NULL),(21,'J\'y étais le mois dernier, exactement la même impression.','