DROP TABLE IF EXISTS `lieu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lieu` (
  `id_lieu` int unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('pays','ville','monument') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monument',
  `icon` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '­ƒôì',
  `nom` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `latitude` decimal(9,6) DEFAULT NULL,
  `longitude` decimal(9,6) DEFAULT NULL,
  `adresse` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_categorie` int unsigned NOT NULL,
  `id_ville` int unsigned NOT NULL,
  PRIMARY KEY (`id_lieu`),
  KEY `idx_lieu_ville` (`id_ville`),
  KEY `idx_lieu_categorie` (`id_categorie`),
  KEY `idx_lieu_coords` (`latitude`,`longitude`),
  CONSTRAINT `fk_lieu_categorie` FOREIGN KEY (`id_categorie`) REFERENCES `categorie_lieu` (`id_categorie`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_lieu_ville` FOREIGN KEY (`id_ville`) REFERENCES `ville` (`id_ville`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_lieu_latitude` CHECK (((`latitude` is null) or (`latitude` between -(90) and 90))),
  CONSTRAINT `chk_lieu_longitude` CHECK (((`longitude` is null) or (`longitude` between -(180) and 180)))
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
