INSERT INTO `lieu` VALUES (1,'monument','📍','Musée de la Médina','Lieu de test pour l’équipe.',34.020000,-6.840000,NULL,'https://images.unsplash.com/photo-1566127444979-b3d2b37dd3cd?w=800&q=80',1,1),(2,'monument','📍','Parc National du Souffle','Lieu de test, deuxième lieu.',34.080000,-6.800000,NULL,'https://picsum.photos/seed/abslieu2/640/400',5,1),(3,'monument','📍','Tour Eiffel','Monument emblématique de Paris, construit en 1889 pour l\'Exposition Universelle.',48.858400,2.294500,NULL,'https://picsum.photos/seed/abslieu3/640/400',4,2),(4,'monument','📍','Musée du Louvre','Le plus grand musée d\'art au monde, abritant la Joconde et la Vénus de Milo.',48.860600,2.337600,NULL,'https://picsum.photos/seed/abslieu4/640/400',1,2),(5,'monument','📍','Jardin Majorelle','Jardin botanique aux couleurs vives, ancienne propriété d\'Yves Saint Laurent.',31.641900,-8.003000,NULL,'https://picsum.photos/seed/abslieu5/640/400',5,4),(6,'monument','📍','Place Jemaa el-Fna','Grande place animée au cœur de Marrakech, classée au patrimoine immatériel de l\'UNESCO.',31.625800,-7.989200,NULL,'https://picsum.photos/seed/abslieu6/640/400',4,4),(7,'monument','📍','Temple de Sensoji','Le plus ancien temple bouddhiste de Tokyo, dans le quartier d\'Asakusa.',35.714800,139.796700,NULL,'https://picsum.photos/seed/abslieu7/640/400',4,6),(8,'monument','📍','Quartier Gion','Quartier des geishas à Kyoto, avec ses maisons en bois et ses ruelles pavées.',35.003500,135.775400,NULL,'https://picsum.photos/seed/abslieu8/640/400',9,7),(9,'monument','📍','Colosseum','Amphithéâtre antique du Ier siècle, symbole de la Rome impériale.',41.890200,12.492200,NULL,'https://picsum.photos/seed/abslieu9/640/400',4,8),(10,'monument','📍','Sagrada Família','Basilique inachevée de Gaudí, chef-d\'œuvre de l\'architecture moderniste catalan.',41.403600,2.174400,NULL,'https://picsum.photos/seed/abslieu10/640/400',4,10),(11,'monument','📍','Monastère des Hiéronymites','Joyau de l\'architecture manuéline à Belém, inscrit à l\'UNESCO.',38.697700,-9.206400,NULL,'https://picsum.photos/seed/abslieu11/640/400',4,12),(12,'monument','📍','Rijksmuseum','Musée national néerlandais avec les chefs-d\'œuvre de Rembrandt et Vermeer.',52.360000,4.885200,NULL,'https://picsum.photos/seed/abslieu12/640/400',1,14),(13,'monument','📍','Central Park','Immense parc urbain au cœur de Manhattan, poumon vert de New York.',40.785100,-73.968300,NULL,'https://picsum.photos/seed/abslieu13/640/400',5,15),(14,'monument','📍','Acropole d\'Athènes','Colline sacrée avec le Parthénon, symbole de la Grèce antique.',37.971500,23.726700,NULL,'https://picsum.photos/seed/abslieu14/640/400',4,16),(15,'monument','📍','Wat Pho','Temple du Bouddha couché à Bangkok, l\'un des plus grands temples de Thaïlande.',13.746500,100.493000,NULL,'https://picsum.photos/seed/abslieu15/640/400',4,17),(16,'monument','📍','Offices de Florence','L\'un des plus grands musées d\'art au monde avec la Naissance de Vénus de Botticelli.',43.768600,11.255300,NULL,'https://picsum.photos/seed/abslieu16/640/400',1,9),(17,'monument','📍','Cathédrale de Séville','La plus grande cathédrale gothique du monde, tombe de Christophe Colomb.',37.386100,-5.992500,NULL,'https://picsum.photos/seed/abslieu17/640/400',4,11),(18,'monument','­ƒôì','Arc de Triomphe','Arc monumental au sommet des Champs-Élysées, dédié aux armées françaises.',48.873800,2.295000,NULL,'https://picsum.photos/seed/abslieu18/640/400',4,2),(19,'monument','­ƒôì','Cathédrale Notre-Dame','Chef-d\'œuvre gothique au cœur de l\'Île de la Cité, en cours de restauration.',48.853000,2.349900,NULL,'https://picsum.photos/seed/abslieu19/640/400',4,2),(20,'monument','­ƒôì','Basilique du Sacré-Cœur','Basilique blanche dominant Paris depuis la butte Montmartre.',48.886700,2.343100,NULL,'https://picsum.photos/seed/abslieu20/640/400',4,2),(21,'monument','­ƒôì','Musée d\'Orsay','Ancienne gare abritant la plus belle collection impressionniste au monde.',48.860000,2.326600,NULL,'https://picsum.photos/seed/abslieu21/640/400',1,2),(