DROP TABLE IF EXISTS `like_avis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `like_avis` (
  `id_utilisateur` int unsigned NOT NULL,
  `id_avis` int unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_utilisateur`,`id_avis`),
  KEY `fk_like_avis_avis` (`id_avis`),
  CONSTRAINT `fk_like_avis_avis` FOREIGN KEY (`id_avis`) REFERENCES `avis` (`id_avis`) ON DELETE CASCADE,
  CONSTRAINT `fk_like_avis_user` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
